return {api_version=1,id="EX1_408",name="Mortal Strike",text="Deal $4 damage. If you have 12 or less Health, deal $6 instead.",set="EXPERT1",type="spell",class="warrior",rarity="rare",cost=4,target_mode="required",targets=function(ctx)return ctx:characters()end,on_play=function(ctx,self,target)local p=ctx:controller(self);local amount=ctx:entity(ctx:player(p).hero).health<=12 and 6 or 4;cardlib.effects.damage(ctx, target,amount)end}
